 43→// runTrailShow shows the trail for the current branch, or falls through to list.
 44→func runTrailShow(w io.Writer) error {
 45→	branch, err := GetCurrentBranch()
 46→	if err != nil {
 47→		return runTrailListAll(w, "", false)
 48→	}
 49→
 50→	repo, err := strategy.OpenRepository()
 51→	if err != nil {
 52→		return fmt.Errorf("failed to open repository: %w", err)
 53→	}
 54→
 55→	store := trail.NewStore(repo)
 56→	metadata, err := store.FindByBranch(branch)
 57→	if err != nil || metadata == nil {
 58→		return runTrailListAll(w, "", false)
 59→	}
 60→
 61→	printTrailDetails(w, metadata)
 62→	return nil
 63→}
 64→
 65→func printTrailDetails(w io.Writer, m *trail.Metadata) {
 66→	fmt.Fprintf(w, "Trail: %s\n", m.Title)
 67→	fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
 68→	fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
 69→	fmt.Fprintf(w, "  Base:    %s\n", m.Base)
 70→	fmt.Fprintf(w, "  Status:  %s\n", m.Status)
 71→	fmt.Fprintf(w, "  Author:  %s\n", m.Author)
 72→	if m.Description != "" {
 73→		fmt.Fprintf(w, "  Description: %s\n", m.Description)
 74→	}
 75→	if len(m.Labels) > 0 {
 76→		fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
 77→	}
 78→	if len(m.Assignees) > 0 {
 79→		fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
 80→	}
 81→	fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format(time.RFC3339))
 82→	fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format(time.RFC3339))
 83→}
