 85→func newTrailListCmd() *cobra.Command {
 86→	var statusFilter string
 87→	var jsonOutput bool
 88→
 89→	cmd := &cobra.Command{
 90→		Use:   "list",
 91→		Short: "List all trails",
 92→		RunE: func(cmd *cobra.Command, _ []string) error {
 93→			return runTrailListAll(cmd.OutOrStdout(), statusFilter, jsonOutput)
 94→		},
 95→	}
 96→
 97→	cmd.Flags().StringVar(&statusFilter, "status", "", "Filter by status (draft, open, in_progress, in_review, done, closed)")
