102→
103→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
104→	repo, err := strategy.OpenRepository()
105→	if err != nil {
106→		return fmt.Errorf("failed to open repository: %w", err)
107→	}
108→
109→	store := trail.NewStore(repo)
110→	trails, err := store.List()
111→	if err != nil {
112→		return fmt.Errorf("failed to list trails: %w", err)
113→	}
114→
115→	if trails == nil {
116→		trails = []*trail.Metadata{}
117→	}
118→
119→	// Apply status filter
120→	if statusFilter != "" {
121→		status := trail.Status(statusFilter)
122→		if !status.IsValid() {
123→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
124→		}
125→		var filtered []*trail.Metadata
126→		for _, t := range trails {
127→			if t.Status == status {
128→				filtered = append(filtered, t)
129→			}
130→		}
131→		trails = filtered
132→	}
133→
134→	// Sort by updated_at descending
135→	sort.Slice(trails, func(i, j int) bool {
136→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
137→	})
138→
139→	if jsonOutput {
140→		enc := json.NewEncoder(w)
141→		enc.SetIndent("", "  ")
142→		if err := enc.Encode(trails); err != nil {
143→			return fmt.Errorf("failed to encode JSON: %w", err)
144→		}
145→		return nil
146→	}
147→
148→	if len(trails) == 0 {
149→		fmt.Fprintln(w, "No trails found.")
150→		fmt.Fprintln(w, "Create one with: entire trail create")
151→		return nil
152→	}
153→
154→	// Table output
155→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
156→	for _, t := range trails {
157→		branch := truncate(t.Branch, 30)
158→		title := truncate(t.Title, 40)
159→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
160→			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
161→	}
162→
163→	return nil
164→}
