186→//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
187→func runTrailCreate(w, errW io.Writer, title, description, base, branch, statusStr string) error {
188→	repo, err := strategy.OpenRepository()
189→	if err != nil {
190→		return fmt.Errorf("failed to open repository: %w", err)
191→	}
192→
193→	// Determine branch
194→	if branch == "" {
195→		branch, err = GetCurrentBranch()
196→		if err != nil {
197→			return fmt.Errorf("failed to determine current branch: %w", err)
198→		}
199→	}
200→
201→	// Check if on default branch
202→	if isDefault, _, defaultErr := IsOnDefaultBranch(); defaultErr == nil && isDefault {
203→		fmt.Fprintln(errW, "Cannot create a trail on the default branch.")
204→		fmt.Fprintln(errW, "Create or switch to a feature branch first.")
205→		return NewSilentError(errors.New("cannot create trail on default branch"))
206→	}
207→
208→	// Determine base branch
209→	if base == "" {
210→		base = strategy.GetDefaultBranchName(repo)
211→		if base == "" {
212→			base = defaultBaseBranch
213→		}
214→	}
215→
216→	// Check if trail already exists for this branch
217→	store := trail.NewStore(repo)
218→	existing, err := store.FindByBranch(branch)
219→	if err == nil && existing != nil {
220→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
221→		return nil
222→	}
223→
224→	// Determine title
225→	if title == "" {
226→		defaultTitle := trail.HumanizeBranchName(branch)
227→
228→		// Interactive mode if flags not provided
229→		if !hasFlag("title") {
230→			var inputTitle string
231→			form := NewAccessibleForm(
232→				huh.NewGroup(
233→					huh.NewInput().
234→						Title("Trail title").
235→						Placeholder(defaultTitle).
236→						Value(&inputTitle),
237→				),
238→			)
239→			if formErr := form.Run(); formErr != nil {
240→				return fmt.Errorf("form cancelled: %w", formErr)
241→			}
242→			if inputTitle != "" {
243→				title = inputTitle
244→			} else {
245→				title = defaultTitle
246→			}
247→		} else {
248→			title = defaultTitle
249→		}
250→	}
251→
252→	// Determine status
253→	var trailStatus trail.Status
254→	if statusStr != "" {
255→		trailStatus = trail.Status(statusStr)
256→		if !trailStatus.IsValid() {
257→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
258→		}
259→	} else {
260→		trailStatus = trail.StatusDraft
261→	}
262→
263→	// Generate trail ID
264→	trailID, err := trail.GenerateID()
265→	if err != nil {
266→		return fmt.Errorf("failed to generate trail ID: %w", err)
267→	}
268→
269→	// Get git author
270→	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)
271→
272→	now := time.Now()
273→	metadata := &trail.Metadata{
274→		TrailID:     trailID,
275→		Branch:      branch,
276→		Base:        base,
277→		Title:       title,
278→		Description: description,
279→		Status:      trailStatus,
280→		Author:      authorName,
281→		Assignees:   []string{},
282→		Labels:      []string{},
283→		CreatedAt:   now,
284→		UpdatedAt:   now,
285→	}
286→
287→	if err := store.Write(metadata, nil); err != nil {
288→		return fmt.Errorf("failed to create trail: %w", err)
289→	}
290→
291→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
292→	return nil
293→}
