317→func runTrailUpdate(w io.Writer, statusStr, title, description, branch string, labelAdd, labelRemove []string) error {
318→	repo, err := strategy.OpenRepository()
319→	if err != nil {
320→		return fmt.Errorf("failed to open repository: %w", err)
321→	}
322→
323→	// Determine branch
324→	if branch == "" {
325→		branch, err = GetCurrentBranch()
326→		if err != nil {
327→			return fmt.Errorf("failed to determine current branch: %w", err)
328→		}
329→	}
330→
331→	store := trail.NewStore(repo)
332→	metadata, err := store.FindByBranch(branch)
333→	if err != nil {
334→		return fmt.Errorf("failed to find trail: %w", err)
335→	}
336→	if metadata == nil {
337→		return fmt.Errorf("no trail found for branch %q", branch)
338→	}
339→
340→	// Validate status if provided
341→	if statusStr != "" {
342→		status := trail.Status(statusStr)
343→		if !status.IsValid() {
344→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
345→		}
346→	}
347→
348→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
349→		if statusStr != "" {
350→			m.Status = trail.Status(statusStr)
351→		}
352→		if title != "" {
353→			m.Title = title
354→		}
355→		if description != "" {
356→			m.Description = description
357→		}
358→		for _, l := range labelAdd {
359→			if !containsString(m.Labels, l) {
360→				m.Labels = append(m.Labels, l)
361→			}
362→		}
363→		for _, l := range labelRemove {
364→			m.Labels = removeString(m.Labels, l)
365→		}
366→	})
367→	if err != nil {
368→		return fmt.Errorf("failed to update trail: %w", err)
369→	}
370→
371→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
372→	return nil
373→}
374→
375→// defaultBaseBranch is the fallback base branch name when it cannot be determined.
376→const defaultBaseBranch = "main"
377→
378→// AutoCreateTrail creates a trail automatically for the current branch if one doesn't exist.
379→// This is called during session start for non-main branches.
380→func AutoCreateTrail(repo *git.Repository, branchName, baseBranch string) error {
381→	store := trail.NewStore(repo)
382→
383→	existing, err := store.FindByBranch(branchName)
384→	if err == nil && existing != nil {
385→		return nil // Trail already exists
386→	}
387→
388→	trailID, err := trail.GenerateID()
389→	if err != nil {
390→		return fmt.Errorf("failed to generate trail ID: %w", err)
391→	}
392→
393→	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)
394→	now := time.Now()
395→
396→	metadata := &trail.Metadata{
397→		TrailID:   trailID,
398→		Branch:    branchName,
399→		Base:      baseBranch,
400→		Title:     trail.HumanizeBranchName(branchName),
401→		Status:    trail.StatusInProgress,
402→		Author:    authorName,
403→		Assignees: []string{},
404→		Labels:    []string{},
405→		CreatedAt: now,
406→		UpdatedAt: now,
407→	}
408→
409→	if err := store.Write(metadata, nil); err != nil {
410→		return fmt.Errorf("failed to create trail: %w", err)
411→	}
412→
413→	fmt.Fprintf(os.Stderr, "[entire] Created trail for branch: %s\n", branchName)
414→	return nil
415→}
