417→// hasFlag is a simple helper that checks os.Args for --flag presence.
418→// Used to distinguish between "flag not provided" and "flag provided with empty value".
419→func hasFlag(name string) bool {
420→	for _, arg := range os.Args {
421→		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
422→			return true
423→		}
424→	}
425→	return false
426→}
427→
428→func truncate(s string, maxLen int) string {
429→	if len(s) <= maxLen {
430→		return s
431→	}
432→	if maxLen <= 3 {
433→		return s[:maxLen]
434→	}
435→	return s[:maxLen-3] + "..."
436→}
437→
438→func formatValidStatuses() string {
439→	statuses := trail.ValidStatuses()
440→	names := make([]string, len(statuses))
441→	for i, s := range statuses {
442→		names[i] = string(s)
443→	}
444→	return strings.Join(names, ", ")
445→}
446→
447→func containsString(slice []string, s string) bool {
448→	for _, v := range slice {
449→		if v == s {
450→			return true
451→		}
452→	}
453→	return false
454→}
455→
456→func removeString(slice []string, s string) []string {
457→	var result []string
458→	for _, v := range slice {
459→		if v != s {
460→			result = append(result, v)
461→		}
462→	}
463→	return result
464→}
