  1→// lifecycle.go implements the generic lifecycle event dispatcher.
  2→// It routes normalized events from any agent to the appropriate framework actions.
  3→//
  4→// The dispatcher inverts the current flow from "agent handler calls framework functions"
  5→// to "framework dispatcher calls agent methods." Agents are passive data providers;
  6→// the dispatcher handles all orchestration: state transitions, strategy calls,
  7→// file change detection, metadata generation.
  8→package cli
  9→
 10→import (
 11→	"context"
 12→	"errors"
 13→	"fmt"
 14→	"log/slog"
 15→	"os"
 16→	"path/filepath"
 17→	"strings"
 18→	"time"
 19→
 20→	"github.com/entireio/cli/cmd/entire/cli/agent"
 21→	"github.com/entireio/cli/cmd/entire/cli/logging"
 22→	"github.com/entireio/cli/cmd/entire/cli/paths"
 23→	"github.com/entireio/cli/cmd/entire/cli/session"
 24→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 25→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 26→	"github.com/entireio/cli/cmd/entire/cli/validation"
 27→)
 28→
 29→// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
 30→// Returns nil if the event was handled successfully.
 31→func DispatchLifecycleEvent(ag agent.Agent, event *agent.Event) error {
 32→	if ag == nil {
 33→		return errors.New("agent cannot be nil")
 34→	}
 35→	if event == nil {
 36→		return errors.New("event cannot be nil")
 37→	}
 38→
 39→	switch event.Type {
 40→	case agent.SessionStart:
 41→		return handleLifecycleSessionStart(ag, event)
 42→	case agent.TurnStart:
 43→		return handleLifecycleTurnStart(ag, event)
 44→	case agent.TurnEnd:
 45→		return handleLifecycleTurnEnd(ag, event)
 46→	case agent.Compaction:
 47→		return handleLifecycleCompaction(ag, event)
 48→	case agent.SessionEnd:
 49→		return handleLifecycleSessionEnd(ag, event)
 50→	case agent.SubagentStart:
 51→		return handleLifecycleSubagentStart(ag, event)
 52→	case agent.SubagentEnd:
 53→		return handleLifecycleSubagentEnd(ag, event)
 54→	default:
 55→		return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
 56→	}
 57→}
 58→
 59→// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
 60→// fires state machine transition.
 61→func handleLifecycleSessionStart(ag agent.Agent, event *agent.Event) error {
 62→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
 63→	logging.Info(logCtx, "session-start",
 64→		slog.String("event", event.Type.String()),
 65→		slog.String("session_id", event.SessionID),
 66→		slog.String("session_ref", event.SessionRef),
 67→	)
 68→
 69→	if event.SessionID == "" {
 70→		return fmt.Errorf("no session_id in %s event", event.Type)
 71→	}
 72→	if err := validation.ValidateSessionID(event.SessionID); err != nil {
 73→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
 74→	}
 75→
 76→	// Build informational message
 77→	message := "\n\nPowered by Entire:\n  This conversation will be linked to your next commit."
 78→
 79→	// Check for concurrent sessions and append count if any
 80→	strat := GetStrategy()
 81→	if concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker); ok {
 82→		if count, err := concurrentChecker.CountOtherActiveSessionsWithCheckpoints(event.SessionID); err == nil && count > 0 {
 83→			message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
 84→		}
 85→	}
 86→
 87→	// Output informational message
 88→	if event.ResponseMessage != "" {
 89→		message = event.ResponseMessage
 90→	}
 91→	if err := outputHookResponse(message); err != nil {
 92→		return err
 93→	}
 94→
 95→	// Fire EventSessionStart for the current session (if state exists).
 96→	if state, loadErr := strategy.LoadSessionState(event.SessionID); loadErr != nil {
 97→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state on start: %v\n", loadErr)
 98→	} else if state != nil {
 99→		if transErr := strategy.TransitionAndLog(state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
100→			fmt.Fprintf(os.Stderr, "Warning: session start transition failed: %v\n", transErr)
101→		}
102→		if saveErr := strategy.SaveSessionState(state); saveErr != nil {
103→			fmt.Fprintf(os.Stderr, "Warning: failed to update session state on start: %v\n", saveErr)
104→		}
105→	}
106→
107→	return nil
108→}
109→
110→// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
111→// ensures strategy setup, initializes session.
112→func handleLifecycleTurnStart(ag agent.Agent, event *agent.Event) error {
113→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
114→	logging.Info(logCtx, "turn-start",
115→		slog.String("event", event.Type.String()),
116→		slog.String("session_id", event.SessionID),
117→		slog.String("session_ref", event.SessionRef),
118→	)
119→
120→	sessionID := event.SessionID
121→	if sessionID == "" {
122→		return fmt.Errorf("no session_id in %s event", event.Type)
123→	}
124→	if err := validation.ValidateSessionID(sessionID); err != nil {
125→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
126→	}
127→
128→	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
129→	if err := CapturePrePromptState(ag, sessionID, event.SessionRef); err != nil {
130→		return err
131→	}
132→
133→	// Ensure strategy setup and initialize session
134→	strat := GetStrategy()
135→
136→	if err := strat.EnsureSetup(); err != nil {
137→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
138→	}
139→
140→	if initializer, ok := strat.(strategy.SessionInitializer); ok {
141→		agentType := ag.Type()
142→		if err := initializer.InitializeSession(sessionID, agentType, event.SessionRef, event.Prompt); err != nil {
143→			fmt.Fprintf(os.Stderr, "Warning: failed to initialize session state: %v\n", err)
144→		}
145→	}
146→
147→	// Auto-create trail for non-main branches
148→	autoCreateTrailOnTurnStart()
149→
150→	return nil
151→}
152→
153→// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
154→// detects file changes, saves step + checkpoint, transitions phase.
155→//
156→//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
157→func handleLifecycleTurnEnd(ag agent.Agent, event *agent.Event) error {
158→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
159→	logging.Info(logCtx, "turn-end",
160→		slog.String("event", event.Type.String()),
161→		slog.String("session_id", event.SessionID),
162→		slog.String("session_ref", event.SessionRef),
163→	)
164→
165→	sessionID := event.SessionID
166→	if sessionID == "" {
167→		sessionID = unknownSessionID
168→	}
169→
170→	transcriptRef := event.SessionRef
171→	if transcriptRef == "" {
172→		return errors.New("transcript file not specified")
173→	}
174→	if !fileExists(transcriptRef) {
175→		return fmt.Errorf("transcript file not found: %s", transcriptRef)
176→	}
177→
178→	// Early check: bail out quickly if the repo has no commits yet.
179→	if repo, err := strategy.OpenRepository(); err == nil && strategy.IsEmptyRepository(repo) {
180→		fmt.Fprintln(os.Stderr, "Entire: skipping checkpoint. Will activate after first commit.")
181→		return NewSilentError(strategy.ErrEmptyRepository)
182→	}
183→
184→	// Create session metadata directory
185→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
186→	sessionDirAbs, err := paths.AbsPath(sessionDir)
187→	if err != nil {
188→		sessionDirAbs = sessionDir
189→	}
190→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
191→		return fmt.Errorf("failed to create session directory: %w", err)
192→	}
193→
194→	// If agent implements TranscriptPreparer, wait for transcript to be ready
195→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
196→		if err := preparer.PrepareTranscript(transcriptRef); err != nil {
197→			fmt.Fprintf(os.Stderr, "Warning: failed to prepare transcript: %v\n", err)
198→		}
199→	}
200→
201→	// Copy transcript to session directory
202→	transcriptData, err := ag.ReadTranscript(transcriptRef)
203→	if err != nil {
204→		return fmt.Errorf("failed to read transcript: %w", err)
205→	}
206→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
207→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
208→		return fmt.Errorf("failed to write transcript: %w", err)
209→	}
210→	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)
211→
212→	// Copy export JSON if it exists alongside the transcript (written by OpenCode plugin).
213→	// This is used by `opencode import` during resume/rewind to restore the session
214→	// into OpenCode's SQLite database with the original session ID.
215→	exportSrc := strings.TrimSuffix(transcriptRef, filepath.Ext(transcriptRef)) + ".export.json"
216→	if exportData, readErr := os.ReadFile(exportSrc); readErr == nil { //nolint:gosec // Path derived from agent hook
217→		exportDest := filepath.Join(sessionDirAbs, paths.ExportDataFileName)
218→		if writeErr := os.WriteFile(exportDest, exportData, 0o600); writeErr != nil {
219→			fmt.Fprintf(os.Stderr, "Warning: failed to write export data: %v\n", writeErr)
220→		}
221→	}
222→
223→	// Load pre-prompt state (captured on TurnStart)
224→	preState, err := LoadPrePromptState(sessionID)
225→	if err != nil {
226→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
227→	}
228→
229→	// Determine transcript offset
230→	transcriptOffset := resolveTranscriptOffset(preState, sessionID)
231→
232→	// Extract metadata via agent interface (prompts, summary, modified files)
233→	var allPrompts []string
234→	var summary string
235→	var modifiedFiles []string
236→	var newTranscriptPosition int
237→
238→	// Compute subagents directory for agents that support subagent extraction.
239→	// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
240→	subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
241→
242→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
243→		// Extract prompts
244→		if prompts, promptErr := analyzer.ExtractPrompts(transcriptRef, transcriptOffset); promptErr != nil {
245→			fmt.Fprintf(os.Stderr, "Warning: failed to extract prompts: %v\n", promptErr)
246→		} else {
247→			allPrompts = prompts
248→		}
249→
250→		// Extract summary
251→		if s, sumErr := analyzer.ExtractSummary(transcriptRef); sumErr != nil {
252→			fmt.Fprintf(os.Stderr, "Warning: failed to extract summary: %v\n", sumErr)
253→		} else {
254→			summary = s
255→		}
256→
257→		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
258→		if subagentExtractor, subOk := ag.(agent.SubagentAwareExtractor); subOk {
259→			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptRef, transcriptOffset, subagentsDir); fileErr != nil {
260→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files (with subagents): %v\n", fileErr)
261→			} else {
262→				modifiedFiles = files
263→			}
264→			// Get position from basic analyzer
265→			if _, pos, posErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); posErr == nil {
266→				newTranscriptPosition = pos
267→			}
268→		} else {
269→			// Fall back to basic extraction (main transcript only)
270→			if files, pos, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
271→				fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files: %v\n", fileErr)
272→			} else {
273→				modifiedFiles = files
274→				newTranscriptPosition = pos
275→			}
276→		}
277→	}
278→
279→	// Write prompts file
280→	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
281→	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
282→	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
283→		return fmt.Errorf("failed to write prompt file: %w", err)
284→	}
285→	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)
286→
287→	// Write summary file
288→	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
289→	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
290→		return fmt.Errorf("failed to write summary file: %w", err)
291→	}
292→	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)
293→
294→	// Generate commit message from last prompt
295→	lastPrompt := ""
296→	if len(allPrompts) > 0 {
297→		lastPrompt = allPrompts[len(allPrompts)-1]
298→	}
299→	commitMessage := generateCommitMessage(lastPrompt)
300→	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)
301→
302→	// Get repo root for path normalization
303→	repoRoot, err := paths.RepoRoot()
304→	if err != nil {
305→		return fmt.Errorf("failed to get repo root: %w", err)
306→	}
307→
308→	var preUntrackedFiles []string
309→	if preState != nil {
310→		fmt.Fprintf(os.Stderr, "Pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
311→		preUntrackedFiles = preState.PreUntrackedFiles()
312→	}
313→
314→	// Detect file changes via git status
315→	changes, err := DetectFileChanges(preUntrackedFiles)
316→	if err != nil {
317→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
318→	}
319→
320→	// Filter and normalize all paths
321→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
322→	var relNewFiles, relDeletedFiles []string
323→	if changes != nil {
324→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
325→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
326→	}
327→
328→	// Filter transcript-extracted files to exclude files already committed to HEAD.
329→	// When an agent commits files mid-turn, those files are condensed by PostCommit
330→	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
331→	// if it exists in HEAD with the same content as the working tree.
332→	relModifiedFiles = filterToUncommittedFiles(relModifiedFiles, repoRoot)
333→
334→	// Check if there are any changes
335→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
336→	if totalChanges == 0 {
337→		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
338→		fmt.Fprintf(os.Stderr, "Skipping commit\n")
339→		transitionSessionTurnEnd(sessionID)
340→		if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
341→			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
342→		}
343→		return nil
344→	}
345→
346→	// Log file changes
347→	logFileChanges(relModifiedFiles, relNewFiles, relDeletedFiles)
348→
349→	// Create context file
350→	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
351→	if err := createContextFile(contextFile, commitMessage, sessionID, allPrompts, summary); err != nil {
352→		return fmt.Errorf("failed to create context file: %w", err)
353→	}
354→	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)
355→
356→	// Get git author
357→	author, err := GetGitAuthor()
358→	if err != nil {
359→		return fmt.Errorf("failed to get git author: %w", err)
360→	}
361→
362→	// Get strategy and agent type
363→	strat := GetStrategy()
364→	agentType := ag.Type()
365→
366→	// Get transcript position/identifier from pre-prompt state
367→	var transcriptIdentifierAtStart string
368→	var transcriptLinesAtStart int
369→	if preState != nil {
370→		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
371→		transcriptLinesAtStart = preState.TranscriptOffset
372→	}
373→
374→	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
375→	var tokenUsage *agent.TokenUsage
376→	if subagentExtractor, ok := ag.(agent.SubagentAwareExtractor); ok {
377→		usage, tokenErr := subagentExtractor.CalculateTotalTokenUsage(transcriptRef, transcriptLinesAtStart, subagentsDir)
378→		if tokenErr != nil {
379→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage (with subagents): %v\n", tokenErr)
380→		} else {
381→			tokenUsage = usage
382→		}
383→	} else if calculator, ok := ag.(agent.TokenCalculator); ok {
384→		// Fall back to basic token calculation (main transcript only)
385→		usage, tokenErr := calculator.CalculateTokenUsage(transcriptRef, transcriptLinesAtStart)
386→		if tokenErr != nil {
387→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
388→		} else {
389→			tokenUsage = usage
390→		}
391→	}
392→
393→	// Build fully-populated step context and delegate to strategy
394→	ctx := strategy.StepContext{
395→		SessionID:                sessionID,
396→		ModifiedFiles:            relModifiedFiles,
397→		NewFiles:                 relNewFiles,
398→		DeletedFiles:             relDeletedFiles,
399→		MetadataDir:              sessionDir,
400→		MetadataDirAbs:           sessionDirAbs,
401→		CommitMessage:            commitMessage,
402→		TranscriptPath:           transcriptRef,
403→		AuthorName:               author.Name,
404→		AuthorEmail:              author.Email,
405→		AgentType:                agentType,
406→		StepTranscriptIdentifier: transcriptIdentifierAtStart,
407→		StepTranscriptStart:      transcriptLinesAtStart,
408→		TokenUsage:               tokenUsage,
409→	}
410→
411→	if err := strat.SaveStep(ctx); err != nil {
412→		return fmt.Errorf("failed to save step: %w", err)
413→	}
414→
415→	// Update session state transcript position for auto-commit strategy
416→	if strat.Name() == strategy.StrategyNameAutoCommit && newTranscriptPosition > 0 {
417→		updateAutoCommitTranscriptPosition(sessionID, newTranscriptPosition)
418→	}
419→
420→	// Transition session phase and cleanup
421→	transitionSessionTurnEnd(sessionID)
422→	if cleanupErr := CleanupPrePromptState(sessionID); cleanupErr != nil {
423→		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
424→	}
425→
426→	return nil
427→}
428→
429→// handleLifecycleCompaction handles context compaction: saves current progress
430→// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
431→// Also resets the transcript offset since the transcript may be truncated.
432→func handleLifecycleCompaction(ag agent.Agent, event *agent.Event) error {
433→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
434→	logging.Info(logCtx, "compaction",
435→		slog.String("event", event.Type.String()),
436→		slog.String("session_id", event.SessionID),
437→	)
438→
439→	// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
440→	sessionID := event.SessionID
441→	sessionState, loadErr := strategy.LoadSessionState(sessionID)
442→	if loadErr != nil {
443→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for compaction: %v\n", loadErr)
444→	}
445→	if sessionState != nil {
446→		if transErr := strategy.TransitionAndLog(sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
447→			fmt.Fprintf(os.Stderr, "Warning: compaction transition failed: %v\n", transErr)
448→		}
449→
450→		// Reset transcript offset since the transcript may be truncated/reorganized
451→		sessionState.CheckpointTranscriptStart = 0
452→
453→		if saveErr := strategy.SaveSessionState(sessionState); saveErr != nil {
454→			fmt.Fprintf(os.Stderr, "Warning: failed to save session state after compaction: %v\n", saveErr)
455→		}
456→	}
457→
458→	fmt.Fprintf(os.Stderr, "Context compaction: transcript offset reset\n")
459→	return nil
460→}
