503→// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
504→func handleLifecycleSubagentEnd(ag agent.Agent, event *agent.Event) error {
505→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "lifecycle"), ag.Name())
506→	logging.Info(logCtx, "subagent-end",
507→		slog.String("event", event.Type.String()),
508→		slog.String("session_id", event.SessionID),
509→		slog.String("tool_use_id", event.ToolUseID),
510→		slog.String("subagent_id", event.SubagentID),
511→	)
512→
513→	// Extract subagent type and description from tool input
514→	subagentType, taskDescription := ParseSubagentTypeAndDescription(event.ToolInput)
515→
516→	// Determine subagent transcript path
517→	transcriptDir := filepath.Dir(event.SessionRef)
518→	var subagentTranscriptPath string
519→	if event.SubagentID != "" {
520→		subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
521→		if !fileExists(subagentTranscriptPath) {
522→			subagentTranscriptPath = ""
523→		}
524→	}
525→
526→	// Log context
527→	fmt.Fprintf(os.Stderr, "[entire] Subagent completed\n")
528→	fmt.Fprintf(os.Stderr, "  Session ID: %s\n", event.SessionID)
529→	fmt.Fprintf(os.Stderr, "  Tool Use ID: %s\n", event.ToolUseID)
530→	if event.SubagentID != "" {
531→		fmt.Fprintf(os.Stderr, "  Agent ID: %s\n", event.SubagentID)
532→	}
533→	if subagentTranscriptPath != "" {
534→		fmt.Fprintf(os.Stderr, "  Subagent Transcript: %s\n", subagentTranscriptPath)
535→	}
536→
537→	// Extract modified files from subagent transcript
538→	var modifiedFiles []string
539→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok {
540→		transcriptToScan := event.SessionRef
541→		if subagentTranscriptPath != "" {
542→			transcriptToScan = subagentTranscriptPath
543→		}
544→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
545→			fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files from subagent: %v\n", fileErr)
546→		} else {
547→			modifiedFiles = files
548→		}
549→	}
550→
551→	// Load pre-task state and detect file changes
552→	preState, err := LoadPreTaskState(event.ToolUseID)
553→	if err != nil {
554→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-task state: %v\n", err)
555→	}
556→	var preUntrackedFiles []string
557→	if preState != nil {
558→		preUntrackedFiles = preState.PreUntrackedFiles()
559→	}
560→	changes, err := DetectFileChanges(preUntrackedFiles)
561→	if err != nil {
562→		fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
563→	}
564→
565→	// Get repo root and normalize paths
566→	repoRoot, err := paths.RepoRoot()
567→	if err != nil {
568→		return fmt.Errorf("failed to get repo root: %w", err)
569→	}
570→
571→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
572→	var relNewFiles, relDeletedFiles []string
573→	if changes != nil {
574→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
575→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
576→	}
577→
578→	// If no changes, skip
579→	if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
580→		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping task checkpoint\n")
581→		_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
582→		return nil
583→	}
584→
585→	// Find checkpoint UUID from main transcript (best-effort)
586→	var checkpointUUID string
587→	// Use the existing CLI-level checkpoint UUID finder
588→	mainLines, _, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
589→	if mainLines != nil {
590→		checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
591→	}
592→
593→	// Get git author
594→	author, err := GetGitAuthor()
595→	if err != nil {
596→		return fmt.Errorf("failed to get git author: %w", err)
597→	}
598→
599→	// Build task checkpoint context
600→	strat := GetStrategy()
601→	agentType := ag.Type()
602→
603→	ctx := strategy.TaskStepContext{
604→		SessionID:              event.SessionID,
605→		ToolUseID:              event.ToolUseID,
606→		AgentID:                event.SubagentID,
607→		ModifiedFiles:          relModifiedFiles,
608→		NewFiles:               relNewFiles,
609→		DeletedFiles:           relDeletedFiles,
610→		TranscriptPath:         event.SessionRef,
611→		SubagentTranscriptPath: subagentTranscriptPath,
612→		CheckpointUUID:         checkpointUUID,
613→		AuthorName:             author.Name,
614→		AuthorEmail:            author.Email,
615→		SubagentType:           subagentType,
616→		TaskDescription:        taskDescription,
617→		AgentType:              agentType,
618→	}
619→
620→	if err := strat.SaveTaskStep(ctx); err != nil {
621→		return fmt.Errorf("failed to save task step: %w", err)
622→	}
623→
624→	_ = CleanupPreTaskState(event.ToolUseID) //nolint:errcheck // best-effort cleanup
625→	return nil
626→}
