675→// createContextFile creates a context.md file for the session checkpoint.
676→// This is a unified version that works for all agents.
677→func createContextFile(contextFile, commitMessage, sessionID string, prompts []string, summary string) error {
678→	var sb strings.Builder
679→
680→	sb.WriteString("# Session Context\n\n")
681→	fmt.Fprintf(&sb, "Session ID: %s\n", sessionID)
682→	fmt.Fprintf(&sb, "Commit Message: %s\n\n", commitMessage)
683→
684→	if len(prompts) > 0 {
685→		sb.WriteString("## Prompts\n\n")
686→		for i, p := range prompts {
687→			fmt.Fprintf(&sb, "### Prompt %d\n\n%s\n\n", i+1, p)
688→		}
689→	}
690→
691→	if summary != "" {
692→		sb.WriteString("## Summary\n\n")
693→		sb.WriteString(summary)
694→		sb.WriteString("\n")
695→	}
696→
697→	if err := os.WriteFile(contextFile, []byte(sb.String()), 0o600); err != nil {
698→		return fmt.Errorf("failed to write context file: %w", err)
699→	}
700→	return nil
701→}
