703→// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
704→// Returns parsed transcript lines for use with FindCheckpointUUID.
705→func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, int, error) {
