764→// autoCreateTrailOnTurnStart creates a trail if on a non-main branch without one.
765→// Non-blocking: logs errors but doesn't fail the session.
766→func autoCreateTrailOnTurnStart() {
767→	isDefault, branchName, err := IsOnDefaultBranch()
768→	if err != nil || isDefault || branchName == "" {
769→		return
770→	}
771→
772→	repo, err := strategy.OpenRepository()
773→	if err != nil {
774→		return
775→	}
776→
777→	baseBranch := strategy.GetDefaultBranchName(repo)
778→	if baseBranch == "" {
779→		baseBranch = defaultBaseBranch
780→	}
781→
782→	if err := AutoCreateTrail(repo, branchName, baseBranch); err != nil {
783→		fmt.Fprintf(os.Stderr, "Warning: failed to auto-create trail: %v\n", err)
784→	}
785→}
