787→// logFileChanges logs the files modified, created, and deleted during a session.
788→func logFileChanges(modified, newFiles, deleted []string) {
789→	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(modified))
790→	for _, file := range modified {
791→		fmt.Fprintf(os.Stderr, "  - %s\n", file)
792→	}
793→	if len(newFiles) > 0 {
794→		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(newFiles))
795→		for _, file := range newFiles {
796→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
797→		}
798→	}
799→	if len(deleted) > 0 {
800→		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(deleted))
801→		for _, file := range deleted {
802→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
803→		}
804→	}
805→}
