 170→			if uninstall {
 171→				return runUninstall(cmd.OutOrStdout(), cmd.ErrOrStderr(), force)
 172→			}
 173→			return runDisable(cmd.OutOrStdout(), useProjectSettings)
 174→		},
 175→	}
 176→
 177→	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Update .entire/settings.json instead of .entire/settings.local.json")
 178→	cmd.Flags().BoolVar(&uninstall, "uninstall", false, "Completely remove Entire from this repository")
 179→	cmd.Flags().BoolVar(&force, "force", false, "Skip confirmation prompt (use with --uninstall)")
 180→
 181→	return cmd
 182→}
