1073→// runUninstall completely removes Entire from the repository.
1074→func runUninstall(w, errW io.Writer, force bool) error {
1075→	// Check if we're in a git repository
1076→	if _, err := paths.RepoRoot(); err != nil {
1077→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
1078→		return NewSilentError(errors.New("not a git repository"))
1079→	}
1080→
1081→	// Gather counts for display
1082→	sessionStateCount := countSessionStates()
1083→	shadowBranchCount := countShadowBranches()
1084→	gitHooksInstalled := strategy.IsGitHookInstalled()
1085→	claudeHooksInstalled := checkClaudeCodeHooksInstalled()
1086→	geminiHooksInstalled := checkGeminiCLIHooksInstalled()
1087→	opencodeHooksInstalled := checkOpenCodeHooksInstalled()
1088→	entireDirExists := checkEntireDirExists()
1089→
1090→	// Check if there's anything to uninstall
1091→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
1092→		shadowBranchCount == 0 && !claudeHooksInstalled && !geminiHooksInstalled && !opencodeHooksInstalled {
1093→		fmt.Fprintln(w, "Entire is not installed in this repository.")
1094→		return nil
1095→	}
1096→
1097→	// Show confirmation prompt unless --force
1098→	if !force {
1099→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
1100→		if entireDirExists {
1101→			fmt.Fprintln(w, "  - .entire/ directory")
1102→		}
1103→		if gitHooksInstalled {
1104→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
1105→		}
1106→		if sessionStateCount > 0 {
1107→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
1108→		}
1109→		if shadowBranchCount > 0 {
1110→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
1111→		}
1112→		var agentNames []string
1113→		if claudeHooksInstalled {
1114→			agentNames = append(agentNames, "Claude Code")
1115→		}
1116→		if geminiHooksInstalled {
1117→			agentNames = append(agentNames, "Gemini CLI")
1118→		}
1119→		if opencodeHooksInstalled {
1120→			agentNames = append(agentNames, "OpenCode")
1121→		}
1122→		if len(agentNames) > 0 {
1123→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(agentNames, ", "))
1124→		}
1125→		fmt.Fprintln(w)
1126→
1127→		var confirmed bool
1128→		form := NewAccessibleForm(
1129→			huh.NewGroup(
1130→				huh.NewConfirm().
1131→					Title("Are you sure you want to uninstall Entire?").
1132→					Affirmative("Yes, uninstall").
1133→					Negative("Cancel").
1134→					Value(&confirmed),
1135→			),
1136→		)
1137→
1138→		if err := form.Run(); err != nil {
1139→			return fmt.Errorf("confirmation cancelled: %w", err)
1140→		}
1141→
1142→		if !confirmed {
1143→			fmt.Fprintln(w, "Uninstall cancelled.")
1144→			return nil
1145→		}
1146→	}
1147→
1148→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1149→
1150→	// 1. Remove agent hooks (lowest risk)
1151→	if err := removeAgentHooks(w); err != nil {
1152→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1153→	}
1154→
1155→	// 2. Remove git hooks
1156→	removed, err := strategy.RemoveGitHook()
1157→	if err != nil {
1158→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1159→	} else if removed > 0 {
1160→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1161→	}
1162→
1163→	// 3. Remove session state files
1164→	statesRemoved, err := removeAllSessionStates()
1165→	if err != nil {
1166→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1167→	} else if statesRemoved > 0 {
1168→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1169→	}
1170→
1171→	// 4. Remove .entire/ directory
1172→	if err := removeEntireDirectory(); err != nil {
1173→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1174→	} else if entireDirExists {
1175→		fmt.Fprintln(w, "  Removed .entire directory")
1176→	}
1177→
1178→	// 5. Remove shadow branches
1179→	branchesRemoved, err := removeAllShadowBranches()
1180→	if err != nil {
1181→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1182→	} else if branchesRemoved > 0 {
1183→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1184→	}
1185→
1186→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1187→	return nil
1188→}
